#!/usr/bin/env bash
# Political-prisoner cases extracted from The Black Panther newspaper, Vol. 14 (Sept. 1975 - Apr. 1976),
# read page-by-page (all 28 issues, ~1,090 pages) from the marxists.org archive.
# RUN ON THE SERVER after review. Idempotent: prisoner:add de-dupes by name, so any of these
# figures already in the database (e.g. from the Vol. 15-19 imports) are simply skipped.
# Continue-on-error so duplicates/failures don't abort the batch:
set +e

# ===== GROUP A -- U.S. political-prisoner cases (62) =====

# Alex Poindexter (NE)
php artisan prisoner:add '{"name": "Alex Poindexter", "first_name": "Alex", "last_name": "Poindexter", "description": "Omaha activist and member of the National Committee to Combat Fascism (a BPP affiliate), convicted with David Rice of the 1970 bombing death of a policeman on the testimony of a 15-year-old who admitted planting the bomb; The Black Panther Vol. 14 no.23 (1976). One of the '\''Omaha Two,'\'' he (Ed Poindexter) remained imprisoned for decades. [Source: The Black Panther (Black Panther Party newspaper), v14 no.23; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "NE", "affiliation": ["National Committee to Combat Fascism"]}'

# Alfonso Ross (NY)
php artisan prisoner:add '{"name": "Alfonso Ross", "first_name": "Alfonso", "last_name": "Ross", "description": "One of the '\''Attica Brothers'\'' charged with kidnapping and unlawful imprisonment for allegedly taking hostages in the 1971 Attica rebellion; The Black Panther Vol. 14 no.12 (1975) reports New York State dropped the charges for lack of evidence. [Source: The Black Panther (Black Panther Party newspaper), v14 no.12; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "aka": "Rahiem Gamba Banga", "state": "NY"}'

# Arthur Barber (NY)
php artisan prisoner:add '{"name": "Arthur Barber", "first_name": "Arthur", "last_name": "Barber", "description": "Bronx man ordered released or retried after nearly 10 years when Judge Constance Baker Motley ruled his murder confession had been obtained through severe police beatings amid '\''a pattern of lawlessness'\''; The Black Panther Vol. 14 no.1 (1975). [Source: The Black Panther (Black Panther Party newspaper), v14 no.1; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "NY"}'

# Bernard Stroble (NY)
php artisan prisoner:add '{"name": "Bernard Stroble", "first_name": "Bernard", "last_name": "Stroble", "description": "One of the '\''Attica Brothers,'\'' tried on murder and kidnapping charges arising from the 1971 Attica rebellion; The Black Panther Vol. 14 (1975) reports he was acquitted after the court found the alleged kidnapping never took place. [Source: The Black Panther (Black Panther Party newspaper), v14 no.1,10; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "aka": "Shango", "state": "NY"}'

# Billy Dean Smith ()
php artisan prisoner:add '{"name": "Billy Dean Smith", "first_name": "Billy", "last_name": "Smith", "description": "Black U.S. Army private court-martialed for '\''fragging'\'' (the grenade killing of two white officers) at a Vietnam base, a prosecution the antiwar and Black movements rallied around; The Black Panther Vol. 14 no.9 (1975), in a Black-history note, records his 1972 acquittal after months of pretrial confinement. [Source: The Black Panther (Black Panther Party newspaper), v14 no.9; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]"}'

# Carlos Feliciano (NY)
php artisan prisoner:add '{"name": "Carlos Feliciano", "first_name": "Carlos", "last_name": "Feliciano", "description": "Puerto Rican independence figure who, The Black Panther Vol. 14 no.4 (1975) reports, recently won his freedom from a bomb-plot frame-up; he joined the U.S. delegation to the international solidarity conference for Puerto Rican independence in Havana. [Source: The Black Panther (Black Panther Party newspaper), v14 no.4; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "NY", "affiliation": ["Puerto Rican independence movement"]}'

# Cheryl Todd (GA)
php artisan prisoner:add '{"name": "Cheryl Todd", "first_name": "Cheryl", "last_name": "Todd", "description": "Black Georgia woman charged with Dessie Woods in the June 1975 death of a white insurance salesman the two women said had kidnapped and sexually threatened them; The Black Panther Vol. 14 no.6 (1975) reports they were first falsely arrested for public drunkenness by the highway patrol. [Source: The Black Panther (Black Panther Party newspaper), v14 no.6; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "GA"}'

# Darryl King (NY)
php artisan prisoner:add '{"name": "Darryl King", "first_name": "Darryl", "last_name": "King", "description": "Black ex-serviceman arrested in 1970 and convicted of killing a New York policeman during a robbery, sentenced to 25 years to life; The Black Panther Vol. 14 no.1 (1975) reports he was beaten and identified through suggestive lineups, that a recanting witness admitted lying, and that his defense committee sought a new trial. [Source: The Black Panther (Black Panther Party newspaper), v14 no.1; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "NY"}'

# David Rice (NE)
php artisan prisoner:add '{"name": "David Rice", "first_name": "David", "last_name": "Rice", "description": "Omaha activist (NCCF, the BPP'\''s affiliate) convicted in the 1970 bombing death of a policeman on the coerced testimony of a 16-year-old; The Black Panther Vol. 14 (1975) reports his politically motivated prosecution, the illegal search of his home, and his appeal. One of the '\''Omaha Two,'\'' he was imprisoned until his death in 2016. [Source: The Black Panther (Black Panther Party newspaper), v14 no.3,4; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "aka": "Mondo we Langa", "state": "NE", "affiliation": ["National Committee to Combat Fascism"]}'

# DeWayne Williams (CA)
php artisan prisoner:add '{"name": "DeWayne Williams", "first_name": "DeWayne", "last_name": "Williams", "description": "Cal State Northridge student beaten by LAPD officers and then convicted, by an 11-white jury, of interfering with a police officer; The Black Panther Vol. 14 no.17 (1976) reports he faced up to a year in jail and set up an appeal fund, calling the arrest a racist frame-up. [Source: The Black Panther (Black Panther Party newspaper), v14 no.17; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "aka": "Waheeb", "state": "CA"}'

# Dessie Woods (GA)
php artisan prisoner:add '{"name": "Dessie Woods", "first_name": "Dessie", "last_name": "Woods", "description": "Black Georgia woman charged, with Cheryl Todd, in the June 1975 death of a white insurance salesman whom the Woods-Todd Defense Committee says had kidnapped and tried to rape the two women; The Black Panther Vol. 14 no.6 (1975) reports she faced a possible death penalty and became a national self-defense cause. She was later convicted and imprisoned. [Source: The Black Panther (Black Panther Party newspaper), v14 no.6; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "aka": "Dessie X. Woods", "state": "GA"}'

# Earnest Ball (AL)
php artisan prisoner:add '{"name": "Earnest Ball", "first_name": "Earnest", "last_name": "Ball", "description": "Alabama prisoner and Inmates For Action (IFA) activist convicted of murdering a policeman he says he shot in self-defense during a raid on his ex-wife'\''s home; The Black Panther Vol. 14 no.7 (1975) reports he was beaten, held in a refrigerated cell and denied medical care at Atmore-Holman, and had appealed to the U.S. Supreme Court. [Source: The Black Panther (Black Panther Party newspaper), v14 no.7; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "AL", "affiliation": ["Inmates For Action"]}'

# Elton Rankin (TX)
php artisan prisoner:add '{"name": "Elton Rankin", "first_name": "Elton", "last_name": "Rankin", "description": "Houston youth grazed by a bullet and beaten by police after a car chase, then charged with five counts of attempted capital murder of a police officer though he fired no shots; The Black Panther Vol. 14 no.26 (1976) presents the charges against the surviving youths as a frame-up. [Source: The Black Panther (Black Panther Party newspaper), v14 no.26; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "TX"}'

# Ernest Graham (CA)
php artisan prisoner:add '{"name": "Ernest Graham", "first_name": "Ernest", "last_name": "Graham", "description": "Black prison activist ('\''Shujaa'\'') charged with Eugene Allen in the 1973 death of a Tracy prison guard and facing a mandatory death sentence in what The Black Panther Vol. 14 (1976) calls a political frame-up; the two said prosecution witnesses were promised parole for their testimony. Graham was ultimately acquitted after repeated trials. [Source: The Black Panther (Black Panther Party newspaper), v14 no.29,30; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "aka": "Shujaa", "state": "CA"}'

# Ethel Rosenberg (NY)
php artisan prisoner:add '{"name": "Ethel Rosenberg", "first_name": "Ethel", "last_name": "Rosenberg", "description": "Executed in 1953 with her husband Julius after conviction for conspiracy to commit espionage, in a case long protested as a political prosecution; The Black Panther Vol. 14 no.13 (1975) covers the release of the secret Rosenberg files. [Source: The Black Panther (Black Panther Party newspaper), v14 no.13; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "NY"}'

# Eugene Allen (CA)
php artisan prisoner:add '{"name": "Eugene Allen", "first_name": "Eugene", "last_name": "Allen", "description": "Young Black '\''life prisoner'\'' and prison activist charged, with Ernest Graham, in the 1973 killing of a guard at the Deuel Vocational Institution (Tracy) and facing a mandatory death sentence; The Black Panther Vol. 14 (1976) reports a first trial ended in a hung jury and that the two say they were scapegoated for being young, Black and political. [Source: The Black Panther (Black Panther Party newspaper), v14 no.29,30; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "CA"}'

# Federico Cintron Fiallo (PR)
php artisan prisoner:add '{"name": "Federico Cintron Fiallo", "first_name": "Federico", "last_name": "Fiallo", "description": "Executive secretary of Puerto Rico'\''s United Workers Movement (MOU) labor federation, arrested in Aug. 1975 by FBI and undercover agents on bank-robbery charges as he prepared to attend a solidarity conference in Havana; The Black Panther Vol. 14 no.6 (1975) reports his attorneys called it an attempt to cripple organized labor and the independence movement. [Source: The Black Panther (Black Panther Party newspaper), v14 no.6; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "PR", "affiliation": ["Puerto Rican independence movement"]}'

# Frank Gaskins (IL)
php artisan prisoner:add '{"name": "Frank Gaskins", "first_name": "Frank", "last_name": "Gaskins", "description": "Black prisoner held two and a half years in the Marion federal penitentiary'\''s behavior-modification unit, taken to St. Louis in Sept. 1975 to be arraigned on charges of assaulting four guards; The Black Panther Vol. 14 no.3 (1975) reports supporters called it a frame-up, since the handcuffed prisoner could not have assaulted four guards. [Source: The Black Panther (Black Panther Party newspaper), v14 no.3; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "aka": "Comrade Ko-Jo", "state": "IL"}'

# Frank Shuford (CA)
php artisan prisoner:add '{"name": "Frank Shuford", "first_name": "Frank", "last_name": "Shuford", "description": "22-year-old Black community activist in Santa Ana convicted in a 1972 police frame-up of shooting two market clerks after he had organized against alcohol sales to minors; The Black Panther Vol. 14 no.2 (1975) reports his own attorney betrayed and testified against him, his first trial hung, and he drew a 30-year sentence and appealed. [Source: The Black Panther (Black Panther Party newspaper), v14 no.2; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "CA"}'

# Frank Smith (NY)
php artisan prisoner:add '{"name": "Frank Smith", "first_name": "Frank", "last_name": "Smith", "description": "'\''Big Black,'\'' one of the '\''Attica Brothers'\'' leaders of the 1971 Attica rebellion; The Black Panther Vol. 14 no.10 (1975) reports that after murder charges were dropped he remained among 11 inmates charged with 34 counts of kidnapping for allegedly holding hostages. He was himself tortured during the retaking of the prison. [Source: The Black Panther (Black Panther Party newspaper), v14 no.10; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "aka": "Big Black", "state": "NY"}'

# Freddie Pitts (FL)
php artisan prisoner:add '{"name": "Freddie Pitts", "first_name": "Freddie", "last_name": "Pitts", "description": "Black man who spent 12 years on Florida'\''s death row, convicted by an all-white jury of the 1963 murders of two white service-station operators — a crime another (white) man confessed to; The Black Panther Vol. 14 (1975) reports he and Wilbert Lee were freed and pardoned by Gov. Reubin Askew. [Source: The Black Panther (Black Panther Party newspaper), v14 no.1,2; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "FL"}'

# Gamba Mani (AL)
php artisan prisoner:add '{"name": "Gamba Mani", "first_name": "Gamba", "last_name": "Mani", "description": "Chairman of the Alabama prison group Inmates For Action (IFA), repeatedly retried on charges arising from a January 1974 Atmore protest against beatings and segregation; The Black Panther Vol. 14 no.9 (1975) reports he sought to move his trial to federal court, arguing the state violated his rights by denying him William Kunstler as counsel. [Source: The Black Panther (Black Panther Party newspaper), v14 no.9; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "aka": "Oscar Johnson", "state": "AL", "affiliation": ["Inmates For Action"]}'

# Gerald Bernard Best (TX)
php artisan prisoner:add '{"name": "Gerald Bernard Best", "first_name": "Gerald", "last_name": "Best", "description": "18-year-old wounded when Houston police riddled a car with bullets, then charged with five counts of attempted capital murder of a police officer despite firing no shots (the gun had been thrown from the car before the chase); The Black Panther Vol. 14 no.26 (1976). [Source: The Black Panther (Black Panther Party newspaper), v14 no.26; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "TX"}'

# Henry Dee (IL)
php artisan prisoner:add '{"name": "Henry Dee", "first_name": "Henry", "last_name": "Dee", "description": "Chicago man convicted with James Sayles and sentenced to death (May 1972), then resentenced to two consecutive 220-to-440-year terms, for a murder he says he did not commit; The Black Panther Vol. 14 no.2 (1975) reports the Yaki Yakubu-Henry Dee Defense Fund'\''s plea for support. [Source: The Black Panther (Black Panther Party newspaper), v14 no.2; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "IL"}'

