php artisan prisoner:add '{"name": "Herman Blyden", "first_name": "Herman", "last_name": "Blyden", "description": "One of the '\''Attica Brothers'\'' rebellion leaders charged with kidnapping and murder of hostages during the 1971 Attica uprising; The Black Panther Vol. 14 no.10 (1975) reports his indictments were dismissed for insufficient evidence. [Source: The Black Panther (Black Panther Party newspaper), v14 no.10; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "NY"}'

# Hosea Williams (GA)
php artisan prisoner:add '{"name": "Hosea Williams", "first_name": "Hosea", "last_name": "Williams", "description": "SCLC leader and Georgia state representative whom The Black Panther Vol. 14 no.7 (1975) reports the Fulton County DA was seeking to imprison and remove from the legislature via a felony charge over an alleged traffic violation; a National Defense Committee headed by Ralph Abernathy, Julian Bond and Dick Gregory formed. [Source: The Black Panther (Black Panther Party newspaper), v14 no.7; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "GA", "affiliation": ["SCLC"]}'

# Inez Garcia (CA)
php artisan prisoner:add '{"name": "Inez Garcia", "first_name": "Inez", "last_name": "Garcia", "description": "Young woman of Puerto Rican and Cuban descent convicted of second-degree murder for killing a man who helped rape her; The Black Panther Vol. 14 (1975-76) reports the California Court of Appeal overturned her five-years-to-life conviction and ordered a new trial, in a case that became a landmark of the women'\''s self-defense movement. [Source: The Black Panther (Black Panther Party newspaper), v14 no.17,19; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "CA"}'

# Irving Flores (PR)
php artisan prisoner:add '{"name": "Irving Flores", "first_name": "Irving", "last_name": "Flores", "description": "Puerto Rican Nationalist imprisoned 22 years for the March 1, 1954 armed protest at the U.S. Capitol; The Black Panther Vol. 14 (1976) names him (Irving Flores Rodriguez) among the longest-held political prisoners in the Western Hemisphere. [Source: The Black Panther (Black Panther Party newspaper), v14 no.26,28; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "PR", "affiliation": ["Puerto Rican Nationalist Party"]}'

# James Sayles (IL)
php artisan prisoner:add '{"name": "James Sayles", "first_name": "James", "last_name": "Sayles", "description": "Chicago man convicted with Henry Dee and sentenced to death (May 1972), then to two consecutive 220-to-440-year terms, in what supporters called a wrongful conviction; The Black Panther Vol. 14 no.2 (1975). Known as Yaki Yakubu, he became a New Afrikan liberation theorist. [Source: The Black Panther (Black Panther Party newspaper), v14 no.2; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "aka": "Yaki Yakubu", "state": "IL"}'

# Jim Grant (NC)
php artisan prisoner:add '{"name": "Jim Grant", "first_name": "Jim", "last_name": "Grant", "description": "Charlotte, N.C. civil-rights activist imprisoned in connection with the anti-racist school struggles of the period; The Black Panther Vol. 14 no.28 (1976) names him among the jailed Southern activists a national campaign sought to free. [Source: The Black Panther (Black Panther Party newspaper), v14 no.28; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "NC"}'

# JoAnne Little (NC)
php artisan prisoner:add '{"name": "JoAnne Little", "first_name": "JoAnne", "last_name": "Little", "description": "Black North Carolina woman who killed a white jailer, Clarence Alligood, as he tried to rape her in her Beaufort County cell; The Black Panther Vol. 14 (1975) covers her historic 1975 acquittal on self-defense grounds after a massive national defense campaign, and the continuing Klan threats against her supporters. [Source: The Black Panther (Black Panther Party newspaper), v14 no.3,4,5,6,15; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "NC"}'

