php artisan prisoner:add '{"name": "Morris White", "first_name": "Morris", "last_name": "White", "description": "Seattle Black Panther Party member arrested and charged with false solicitation, disorderly conduct and resisting arrest while selling The Black Panther and running the Free Breakfast program; The Black Panther Vol. 14 no.19 (1976) reports the charges were cleared on appeal after an officer admitted arresting him to make him change his soliciting. [Source: The Black Panther (Black Panther Party newspaper), v14 no.19; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "WA", "affiliation": ["Black Panther Party"]}'

# Olga Talamante (CA)
php artisan prisoner:add '{"name": "Olga Talamante", "first_name": "Olga", "last_name": "Talamante", "description": "UC Santa Cruz graduate from Gilroy, California, imprisoned 16 months in Argentina on false charges of political subversion and tortured with cattle prods until she signed a confession; The Black Panther Vol. 14 no.30 (1976) reports her release and return home after a Bay Area defense campaign. [Source: The Black Panther (Black Panther Party newspaper), v14 no.30; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "CA"}'

# Ormistan Spencer (NY)
php artisan prisoner:add '{"name": "Ormistan Spencer", "first_name": "Ormistan", "last_name": "Spencer", "description": "Rosedale, Queens man arrested and charged with reckless endangerment and weapons offenses after defending his family'\''s home from a racist mob that had repeatedly firebombed it; The Black Panther Vol. 14 no.7 (1975) reports police arrested him rather than the attackers and a rally demanded the charges be dropped. [Source: The Black Panther (Black Panther Party newspaper), v14 no.7; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "aka": "Tony Spencer", "state": "NY"}'

# Oscar Collazo (PR)
php artisan prisoner:add '{"name": "Oscar Collazo", "first_name": "Oscar", "last_name": "Collazo", "description": "Puerto Rican Nationalist imprisoned about 25 years for the 1950 armed attack on Blair House; The Black Panther Vol. 14 (1976) describes him, held at Leavenworth, as among the longest-held political prisoners in the Western Hemisphere, with the PSP campaigning for the nationalists'\'' unconditional release. [Source: The Black Panther (Black Panther Party newspaper), v14 no.26,28; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "PR", "affiliation": ["Puerto Rican Nationalist Party"]}'

# Philip Allen (CA)
php artisan prisoner:add '{"name": "Philip Allen", "first_name": "Philip", "last_name": "Allen", "description": "Young Black Los Angeles college student convicted in what The Black Panther Vol. 14 (1975) calls a police-murder frame-up; the paper reports his appeal-bond was revoked after he spoke at rallies for himself and the San Quentin 6, and that the ACLU entered his case. [Source: The Black Panther (Black Panther Party newspaper), v14 no.4,9; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "CA"}'

# Rafael Cancel Miranda (PR)
php artisan prisoner:add '{"name": "Rafael Cancel Miranda", "first_name": "Rafael", "last_name": "Miranda", "description": "Puerto Rican Nationalist imprisoned 22 years for the March 1, 1954 armed protest at the U.S. Capitol; The Black Panther Vol. 14 (1976) names him among the longest-held political prisoners in the Western Hemisphere. [Source: The Black Panther (Black Panther Party newspaper), v14 no.26,28; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "PR", "affiliation": ["Puerto Rican Nationalist Party"]}'

# Raymond Sumter (NY)
php artisan prisoner:add '{"name": "Raymond Sumter", "first_name": "Raymond", "last_name": "Sumter", "description": "One of the '\''Attica Brothers'\'' whose kidnapping/unlawful-imprisonment charges from the 1971 rebellion were dropped by New York State; The Black Panther Vol. 14 no.12 (1975). [Source: The Black Panther (Black Panther Party newspaper), v14 no.12; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "aka": "Fish Samabi", "state": "NY"}'

# Robert F. Williams (NC)
php artisan prisoner:add '{"name": "Robert F. Williams", "first_name": "Robert", "last_name": "Williams", "description": "Former Monroe, N.C. NAACP president and pioneer of armed Black self-defense (author of '\''Negroes with Guns'\''), who spent years in exile over 1961 '\''kidnapping'\'' charges he called an FBI-driven frame-up; The Black Panther Vol. 14 (1975-76) reports the Michigan Supreme Court refused to extradite him as he returned to face the charges. [Source: The Black Panther (Black Panther Party newspaper), v14 no.13,16; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "NC"}'

# Roger Champen (NY)
php artisan prisoner:add '{"name": "Roger Champen", "first_name": "Roger", "last_name": "Champen", "description": "One of the '\''Attica Brothers'\'' leaders of the 1971 Attica rebellion; The Black Panther Vol. 14 no.10 (1975) reports that after murder charges were dropped he remained among 11 inmates charged with 34 counts of kidnapping. [Source: The Black Panther (Black Panther Party newspaper), v14 no.10; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "NY"}'

# Rommie Loudd (FL)
php artisan prisoner:add '{"name": "Rommie Loudd", "first_name": "Rommie", "last_name": "Loudd", "description": "Pro football'\''s first Black owner (of the WFL'\''s Florida Blazers), jailed in Orlando on drug and embezzlement charges under a bond he could not pay; The Black Panther Vol. 14 no.21 (1976) reports his lawyer and Black Sports magazine called it a racist plot to drive him out of the business. [Source: The Black Panther (Black Panther Party newspaper), v14 no.21; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "FL"}'

# Ronald Lyons (NY)
php artisan prisoner:add '{"name": "Ronald Lyons", "first_name": "Ronald", "last_name": "Lyons", "description": "One of the '\''Attica Brothers'\'' whose kidnapping/unlawful-imprisonment charges from the 1971 rebellion were dismissed before trial; The Black Panther Vol. 14 no.12 (1975). [Source: The Black Panther (Black Panther Party newspaper), v14 no.12; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "NY"}'

# Roy Lee Patterson (GA)
php artisan prisoner:add '{"name": "Roy Lee Patterson", "first_name": "Roy", "last_name": "Patterson", "description": "25-year-old Black Marine sergeant sentenced to natural life by a majority-white Cordele, Georgia jury for the shooting deaths of a state trooper and a policeman after a trooper attacked him, his wife and baby; The Black Panther Vol. 14 no.12 (1975) reports he was denied defense funds and that the Southern Poverty Law Center was appealing. [Source: The Black Panther (Black Panther Party newspaper), v14 no.12; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "GA"}'

# Sarah Bad Heart Bull (SD)
php artisan prisoner:add '{"name": "Sarah Bad Heart Bull", "first_name": "Sarah", "last_name": "Bull", "description": "Mother of a slain Sioux youth who was choked and beaten by a state trooper when she was denied entry to the 1973 Custer, S.D. courthouse; The Black Panther Vol. 14 no.27 (1976) reports she was sentenced to one-to-three years and served six months while her son'\''s white killer got probation. [Source: The Black Panther (Black Panther Party newspaper), v14 no.27; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "SD", "affiliation": ["American Indian Movement"]}'

# Terry Phillips (CA)
php artisan prisoner:add '{"name": "Terry Phillips", "first_name": "Terry", "last_name": "Phillips", "description": "White Panther Party member convicted with Tom Stevens and sentenced to 5½ years-to-life over the July 1974 police raid on the party'\''s San Francisco food-program office; The Black Panther Vol. 14 (1975) reports a 5,000-signature petition demanded an appeal bond. [Source: The Black Panther (Black Panther Party newspaper), v14 no.17,20; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "CA", "affiliation": ["White Panther Party"]}'

# Tom Stevens (CA)
php artisan prisoner:add '{"name": "Tom Stevens", "first_name": "Tom", "last_name": "Stevens", "description": "White Panther Party member sentenced to 5½ years-to-life for assault with a deadly weapon after firing warning shots during a July 1974 San Francisco police raid on the party'\''s Page Street food-program office (which police then set afire); The Black Panther Vol. 14 (1975) reports he was denied bail pending appeal in what supporters called a trumped-up prosecution. [Source: The Black Panther (Black Panther Party newspaper), v14 no.17,20; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "CA", "affiliation": ["White Panther Party"]}'

# Vernon Benton (TX)
php artisan prisoner:add '{"name": "Vernon Benton", "first_name": "Vernon", "last_name": "Benton", "description": "Black Panther Party member held at the Harris County Rehabilitation Center in Houston after a July 1974 police frame-up on unsolved robbery charges; The Black Panther Vol. 14 (1975) reports his life was threatened and that he survived an administration-instigated assault by '\''building tenders'\'' before being put in solitary. [Source: The Black Panther (Black Panther Party newspaper), v14 no.3,4,6,16; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "aka": "T.C. Benton", "state": "TX", "affiliation": ["Black Panther Party"]}'

# Wesley Robert Wells (CA)
php artisan prisoner:add '{"name": "Wesley Robert Wells", "first_name": "Wesley", "last_name": "Wells", "description": "California'\''s longest-held prisoner, who spent 47 of his 66 years behind bars — including years on San Quentin'\''s death row after a 1944 death sentence for throwing a spittoon at a guard — before his sentence was commuted and he was released in 1974; The Black Panther Vol. 14 no.19 (1976) honored him on his death, calling him a prison-movement pioneer. [Source: The Black Panther (Black Panther Party newspaper), v14 no.19; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "CA"}'

# Wilbert Lee (FL)
php artisan prisoner:add '{"name": "Wilbert Lee", "first_name": "Wilbert", "last_name": "Lee", "description": "Imprisoned 12 years with Freddie Pitts for the 1963 Florida service-station murders another man confessed to; convicted by an all-white jury and sentenced to death before being pardoned by Gov. Askew; The Black Panther Vol. 14 (1975). [Source: The Black Panther (Black Panther Party newspaper), v14 no.1,2; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "FL"}'

# William Ortiz (NY)
php artisan prisoner:add '{"name": "William Ortiz", "first_name": "William", "last_name": "Ortiz", "description": "One of the '\''Attica Brothers'\'' whose kidnapping and unlawful-imprisonment charges from the 1971 rebellion were dismissed as prosecutors conceded insufficient evidence; The Black Panther Vol. 14 no.12 (1975). [Source: The Black Panther (Black Panther Party newspaper), v14 no.12; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "aka": "Toriano", "state": "NY"}'

# Willie Burnett (KY)
php artisan prisoner:add '{"name": "Willie Burnett", "first_name": "Willie", "last_name": "Burnett", "description": "Black Kentucky man convicted in 1974 and sentenced to life without parole for the rape of a white woman he says he did not commit; The Black Panther Vol. 14 no.9 (1975) reports the state appeals court overturned the conviction for insufficient evidence and freed him on bond, and that he refused to plea-bargain. [Source: The Black Panther (Black Panther Party newspaper), v14 no.9; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "KY"}'

# Yvonne Wanrow (WA)
php artisan prisoner:add '{"name": "Yvonne Wanrow", "first_name": "Yvonne", "last_name": "Wanrow", "description": "Colville Indian mother sentenced to up to 25 years for the self-defense shooting of a white convicted child molester who had assaulted her children; The Black Panther Vol. 14 no.15 (1975) reports an all-white jury convicted her after the man'\''s record was ruled inadmissible, and that her landmark conviction was overturned on appeal. [Source: The Black Panther (Black Panther Party newspaper), v14 no.15; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]", "state": "WA"}'

