# php artisan prisoner:add '{"name": "Sheila Cassidy", "first_name": "Sheila", "last_name": "Cassidy", "description": "British surgeon held nearly two months as a political prisoner by Chile'\''s junta after she treated a wounded revolutionary; The Black Panther Vol. 14 no.18 (1976) reports she was stripped, given severe electric shocks and held in solitary before her release. [Source: The Black Panther (Black Panther Party newspaper), v14 no.18; digitized at marxists.org — https://www.marxists.org/history/usa/pubs/black-panther/index.htm]"}'

